import typing
from jsilib import _utils
from jsilib.aio.interface import IReactor
from jsilib.transport.frames import Ping, Pong
from jsilib.transport.interface import ITransportConnection

from . import exc as jsi_exc
from .settings import Settings


class KeepAliveWatchdog:
    """An async service that is sending pings to remote peer to keep the
    connection alive."""
    # TODO: This class is tested already, but a separate suite of unit tests
    # would be appreciated to test it even better.

    # TODO: Maybe this one could also be used by JSIConnection class?

    def __init__(self, reactor: IReactor, transport_connection: ITransportConnection, settings: Settings):
        self._reactor = reactor
        self._transport_connection = transport_connection
        self._settings = settings
        self._pending_ping_frames = {}
        self._ping_task_id = None
        self._connection_lost_handler = None

    def register_connection_lost_handler(self, func: typing.Callable[[Exception], None]):
        """Register callback to be triggered once keep alive watchdog
        determines connection to be lost.

        :param func:
            The handler function.

            Called with exception object explaining why the connection is
            considered lost.
        """
        self._connection_lost_handler = func

    def start(self):
        """Start the service."""
        if self._ping_task_id is not None or self._settings.ping_idle_time <= 0.0:
            return
        self._pending_ping_frames.clear()
        self._ping_task_id = self._reactor.call_later(self._settings.ping_idle_time, self._send_next_ping)

    def restart(self):
        """Restart the service.

        This is useful from connection to stop the watchdog from sending
        another PING when other frame was just received.
        """
        self.stop()
        self.start()

    def stop(self):
        """Stop the service."""
        if self._ping_task_id is None:
            return
        self._reactor.cancel(self._ping_task_id)
        self._ping_task_id = None

    def dispatch_pong(self, pong: Pong) -> bool:
        """Dispatch received PONG frame and return True if this was a valid
        PONG or False otherwise."""
        deleted_ping = self._pending_ping_frames.pop(pong.ping_id, None)
        if deleted_ping is None:
            return False  # PONG with invalid id?
        return True

    def _notify_connection_lost_handler(self, exc: Exception):
        if self._connection_lost_handler is not None:
            self._connection_lost_handler(exc)

    def _get_next_ping_delay(self) -> float:
        return self._settings.ping_idle_time ** len(self._pending_ping_frames)

    def _send_next_ping(self):
        def is_socket_still_sending_previous_data() -> bool:
            return self._transport_connection.get_write_buffer_size() > 0

        if is_socket_still_sending_previous_data() :
            self._ping_task_id = self._reactor.call_later(self._get_next_ping_delay(), self._send_next_ping)
            return

        ping = Ping(_utils.next_unique_id(Ping))
        self._pending_ping_frames[ping.ping_id] = ping
        if len(self._pending_ping_frames) > self._settings.ping_loss_threshold:
            self._notify_connection_lost_handler(jsi_exc.ConnectionClosedByPingLoss())
        elif self._transport_connection.is_closed():
            self._notify_connection_lost_handler(jsi_exc.ConnectionClosedByTransport())
        else:
            self._transport_connection.send_nowait(ping)
            self._ping_task_id = self._reactor.call_later(self._get_next_ping_delay(), self._send_next_ping)
